<?php
declare(strict_types=1);
final class BusController {
 public function index(PDO $pdo): void { require_role(['admin']); $rows=$pdo->query('SELECT b.*,u.full_name AS driver_name,s.route_name FROM buses b LEFT JOIN users u ON u.id=b.driver_id LEFT JOIN schedule_entries s ON s.id=b.route_id ORDER BY b.id DESC')->fetchAll(); require __DIR__.'/../views/buses/index.html'; }
 public function save(PDO $pdo): void {
  require_role(['admin']); verify_csrf(); $id=(int)($_POST['id']??0); $number=post_string('bus_number',30); $plate=strtoupper(post_string('plate_number',20)); $capacity=filter_var($_POST['capacity']??null,FILTER_VALIDATE_INT); $driver=($_POST['driver_id']??'')===''?null:(int)$_POST['driver_id']; $route=($_POST['route_id']??'')===''?null:(int)$_POST['route_id'];
  if($number===''||$plate===''||!$capacity||$capacity<1) throw new InvalidArgumentException('Provide a bus number, plate number and positive capacity.');
  if($driver!==null){$q=$pdo->prepare("SELECT id FROM users WHERE id=? AND role='driver' AND is_active=1");$q->execute([$driver]);if(!$q->fetch())throw new InvalidArgumentException('Select an active driver account.');}
  if($route!==null){$q=$pdo->prepare('SELECT id FROM schedule_entries WHERE id=?');$q->execute([$route]);if(!$q->fetch())throw new InvalidArgumentException('Select an existing route.');}
  $photo=null; if(isset($_FILES['photo'])&&$_FILES['photo']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['photo'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>5242880)throw new InvalidArgumentException('Bus photo must be an image under 5 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime]))throw new InvalidArgumentException('Upload a JPG, PNG or WebP photo.');$dir=__DIR__.'/../../public/uploads/buses';if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('Unable to prepare photo storage.');$photo=bin2hex(random_bytes(20)).'.'.$types[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$photo))throw new RuntimeException('Unable to save bus photo.');}
  if($id){$q=$pdo->prepare('UPDATE buses SET bus_number=?,plate_number=?,capacity=?,driver_id=?,route_id=?,photo_filename=COALESCE(?,photo_filename) WHERE id=?');$q->execute([$number,$plate,$capacity,$driver,$route,$photo,$id]);}else{$q=$pdo->prepare('INSERT INTO buses(bus_number,plate_number,capacity,driver_id,route_id,photo_filename) VALUES(?,?,?,?,?,?)');$q->execute([$number,$plate,$capacity,$driver,$route,$photo]);} flash('Bus saved.');redirect('index.php?page=buses');
 }
 public function delete(PDO $pdo): void { require_role(['admin']);verify_csrf();$q=$pdo->prepare('DELETE FROM buses WHERE id=?');$q->execute([(int)($_POST['id']??0)]);flash('Bus deleted (only when no linked records prevent deletion).');redirect('index.php?page=buses'); }
 public function edit(PDO $pdo): void { require_role(['admin']);$q=$pdo->prepare('SELECT * FROM buses WHERE id=?');$q->execute([(int)($_GET['id']??0)]);$bus=$q->fetch();if(!$bus){http_response_code(404);exit('Bus not found.');}$drivers=$pdo->query("SELECT id,full_name FROM users WHERE role='driver' AND is_active=1 ORDER BY full_name")->fetchAll();$routes=$pdo->query('SELECT id,route_name,day_of_week,origin_location,destination_location FROM schedule_entries ORDER BY route_name,day_of_week')->fetchAll();require __DIR__.'/../views/buses/form.html'; }
 public function create(PDO $pdo): void { require_role(['admin']);$bus=null;$drivers=$pdo->query("SELECT id,full_name FROM users WHERE role='driver' AND is_active=1 ORDER BY full_name")->fetchAll();$routes=$pdo->query('SELECT id,route_name,day_of_week,origin_location,destination_location FROM schedule_entries ORDER BY route_name,day_of_week')->fetchAll();require __DIR__.'/../views/buses/form.html'; }
}
